        if self.current_char == '(':
            self.advance()  # Skip '('
            result = self.expr_evaluator()
            self.advance()  # Skip ')'
            return result
        else:
            return self.number()

    def term(self):
        result = self.factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            op = self.current_char
            self.advance()
            if op == '*':
