class ExpressionEvaluator:
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0

    def parse(self):
        self.position = 0
        return self._parse_expression()

    def _parse_expression(self):
        values = [self._parse_term()]

        while self.position < len(self.expression):
            self._skip_whitespace()
            if self.position < len(self.expression):
                operator = self.expression[self.position]
                if operator in ('+', '-'):
                    self.position += 1
                    values.append(operator)
                    values.append(self._parse_term())
                else:
                    break

        return self._evaluate_expression(values)

    def _parse_term(self):
        values = [self._parse_factor()]

        while self.position < len(self.expression):
            self._skip_whitespace()
            if self.position < len(self.expression):
                operator = self.expression[self.position]
                if operator in ('*', '/'):
                    self.position += 1
                    values.append(operator)
                    values.append(self._parse_factor())
                else:
                    break

        return self._evaluate_term(values)

    def _parse_factor(self):
        self._skip_whitespace()
        if self.position < len(self.expression):
            if self.expression[self.position] == '(':
                self.position += 1
                value = self._parse_expression()
                self.position += 1  # Skip past ')'
                return value
            else:
                start = self.position
                while (self.position < len(self.expression) and
                       (self.expression[self.position].isdigit() or
                        self.expression[self.position] == '.' or
                        self.expression[self.position] == '-')):
                    self.position += 1
                return float(self.expression[start:self.position])

    def _skip_whitespace(self):
        while (self.position < len(self.expression) and
               self.expression[self.position].isspace()):
            self.position += 1

    def _evaluate_term(self, values):
        total = values[0]
